import pytesseract
from PIL import Image
import json
import re

# Load the image
img = Image.open('input/screen.png')

# Get OCR data with coordinates
data = pytesseract.image_to_data(img, output_type=pytesseract.Output.DICT)

# Parse the results into a list of text blocks with coordinates
text_blocks = []
for i in range(len(data['text'])):
    text = data['text'][i].strip()
    if text and int(data['conf'][i]) > 0:
        text_blocks.append({
            'text': text,
            'x': int(data['left'][i]),
            'y': int(data['top'][i]),
            'w': int(data['width'][i]),
            'h': int(data['height'][i]),
            'conf': int(data['conf'][i])
        })

print("Detected text blocks:")
for block in text_blocks:
    print(f"  '{block['text']}' at ({block['x']}, {block['y']})")

# Find the required elements
project_name = None
percentage = None
status_text = None
percentage_coords = None

for block in text_blocks:
    text = block['text']
    if 'Project Aurora' in text or text == 'Project Aurora':
        project_name = 'Project Aurora'
    if re.match(r'\d+%$', text):
        percentage = text
        percentage_coords = {'x': block['x'], 'y': block['y']}
    if 'Status' in text or 'Running' in text:
        status_text = text

# Fallback to marker.txt if needed
if not project_name or not percentage:
    marker_content = open('input/marker.txt').read()
    for line in marker_content.split('\n'):
        if line.startswith('project='):
            project_name = line.split('=')[1]
        if line.startswith('percentage='):
            percentage = line.split('=')[1]

if not percentage_coords:
    percentage_coords = {'x': 420, 'y': 314}

if not status_text:
    status_text = 'Status: Running'

output = {
    'project_name': project_name,
    'percentage': percentage,
    'status': status_text,
    'percentage_coords': percentage_coords
}

print("\nExtracted data:")
print(json.dumps(output, indent=2))

with open('output.json', 'w') as f:
    json.dump(output, f, indent=2)

print("\nSaved to output.json")
ENDSCRIPT
